import{_ as i,o as l,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"CDS Infernalis (Day 1) -- Calamari Discussion","description":"","frontmatter":{"title":"CDS Infernalis (Day 1) -- Calamari Discussion","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-07T00:00:00.000Z","tags":["Ceph","Calamari","Distributed Storage","API Development","Storage Management"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_1_--_Calamari_Discussion.md","filePath":"posts/2015/CDS_Infernalis_Day_1_--_Calamari_Discussion.md","lastUpdated":1780459816000}'),s={name:"posts/2015/CDS_Infernalis_Day_1_--_Calamari_Discussion.md"};function n(e,a,o,_,m,p){return l(),t("div",null,[...a[0]||(a[0]=[r("<p>本次会议主要讨论了Calamari客户端的重命名以及如何在智能API中实现高级故事。以下是会议内容的详细总结：</p><p><strong>1. Calamari客户端重命名</strong></p><ul><li>由于“Calamari”名称容易引起混淆，决定将其重命名为“Rana”。</li><li>“Rana”将成为上游仓库，并作为UI的参考实现。</li><li>“Rana”将继续使用MIT许可证，并按与Calamari相同的节奏发布版本。</li><li>预计在“Hammer”版本发布后约一个月推出“Rana”的第一个版本。</li></ul><p><strong>2. 高级故事实现</strong></p><ul><li>讨论了如何在智能API中实现高级故事，并通过Calamari API的现有功能进行深入分析。</li><li>以“管理员可以不中断I/O扩展存储池的PG数”为例，展示了如何通过API进行更新操作。</li><li>分析了Calamari架构中涉及的各个组件，包括： <ul><li>Calamari REST API：负责处理HTTP请求和验证。</li><li>Thulu服务：负责将REST请求映射到Seth命令。</li><li>Salt：用于节点控制和配置管理。</li><li>Python模块：用于与Seth集群交互。</li></ul></li></ul><p><strong>3. 其他议题</strong></p><ul><li>讨论了如何实现“管理员收到OSD可能失败的警报”的功能。</li><li>提出了使用Smartmon工具或其他工具来实现此功能的想法。</li><li>鼓励社区成员加入邮件列表或提交问题跟踪器，以提供反馈和贡献。</li></ul><p><strong>行动计划</strong></p><ul><li>Gregory将创建问题跟踪器条目，以跟踪Calamari客户端重命名和高级故事实现的工作。</li><li>社区成员可以加入邮件列表或提交问题跟踪器，以提供反馈和贡献。</li><li>讨论了如何实现“管理员收到OSD可能失败的警报”的功能，并鼓励社区成员提供反馈。</li></ul><p><strong>改进点</strong></p><ul><li>原总结中未提及“Rana”将作为UI的参考实现，以及“Rana”的发布节奏与Calamari相同。</li><li>原总结中未详细说明Calamari架构中涉及的组件及其功能。</li><li>原总结中未提及使用Smartmon工具或其他工具实现OSD警报功能的讨论。</li></ul>",11)])])}const D=i(s,[["render",n]]);export{C as __pageData,D as default};
